const hoyStr = new Date().toISOString().slice(0, 10);

// Simulación de alerta meteorológica activa en la región norte/caribe
const alertaActiva = true; 
const regionAfectada = 'La Fortuna y Zona Norte';

const items = $input.all().map(i => i.json).filter(b => {
  const esHoy = String(b.date || '').slice(0, 10) === hoyStr;
  const esZona = String(b.tourName || '').toLowerCase().includes('arenal') || String(b.tourName || '').toLowerCase().includes('fortuna') || String(b.tourName || '').toLowerCase().includes('sarapiquí');
  return esHoy && esZona;
});

if (!alertaActiva || items.length === 0) {
  return [{ json: { status: 'sin_alertas_meteorologicas', message: 'Condiciones normales en todas las rutas operativas.' } }];
}

return items.map(item => ({
  json: {
    bookingId: item.bookingId,
    customerName: item.customerName || 'Viajero',
    customerEmail: item.customerEmail,
    customerPhone: item.customerPhone,
    tourName: item.tourName,
    providerId: item.providerId || 'proveedor-directo-crtours',
    alertaClima: `⚠️ [AVISO CLIMÁTICO COSTA RICA TOURS]: Estimado/a ${item.customerName || 'Viajero'}, debido a condiciones de temporal/lluvia en ${regionAfectada} para tu tour de hoy (${item.tourName}), nuestro equipo y el operador logístico (Alsama Tours CR / Expediciones Tropicales) hemos activado protocolos de seguridad preventivos. Tu guía se comunicará contigo 1 hora antes para coordinar ajustes menores de ruta garantizando tu seguridad y comodidad. ¡Pura Vida! 🌿`
  }
}));
